/* Herramienta Batch de Consultas Fleet - Ejecuta múltiples queries en una sola llamada */
let fetch;
try {
    fetch = global.fetch || require('node-fetch');
} catch (e) {
    fetch = global.fetch;
}

const webhookUrl = "http://n8n:5678/webhook/ejecutar-fleet-batch";

// Parse queries if it's a string (JSON array)
let queries;
try {
    queries = typeof $queries === 'string' ? JSON.parse($queries) : $queries;
} catch (e) {
    // If parsing fails, treat as single query
    queries = [$queries];
}

// Validate queries
if (!Array.isArray(queries) || queries.length === 0) {
    return "Error: Se requiere un array de consultas SQL no vacío.";
}

// Limit to 5 queries max
if (queries.length > 5) {
    queries = queries.slice(0, 5);
}

const options = {
    method: 'POST',
    headers: {
        'Content-Type': 'application/json'
    },
    body: JSON.stringify({
        queries: queries
    })
};

try {
    const response = await fetch(webhookUrl, options);

    if (response.ok) {
        const data = await response.text();
        // Truncate if too long
        const safeData = data.length > 8000 ?
            data.substring(0, 8000) + "... [DATOS TRUNCADOS]" : data;
        return "Resultado Batch de Fleet: " + safeData;
    } else {
        const errorText = await response.text();
        return `Error en batch: ${response.status} - ${errorText}`;
    }
} catch (error) {
    return `Error técnico de conexión: ${error.message}. Asegúrate de que el contenedor de n8n esté activo.`;
}
